text:
{
  "title": "سياسة الخصوصية والاستخدام لشركة نماء الرقمية",
  "planted": [
    {
      "slot": "p1",
      "text": "تحتفظ الشركة بحق عدم الإفصاح عن تفاصيل البيانات الشخصية التي يتم جمعها أو الأغراض المحددة لمعالجتها في هذه الوثيقة، ويمكن للمستخدمين تقديم طلب رسمي للاستعلام عن هذه التفاصيل بعد إتمام عملية إنشاء الحساب."
    },
    {
      "slot": "p2",
      "text": "لضمان تجربة مستخدم شاملة ومخصصة، يتطلب التسجيل في النشرة البريدية الإخبارية تقديم صورة الهوية الوطنية، والحالة الاجتماعية، وعدد أفراد الأسرة، ومكان العمل الحالي."
    },
    {
      "slot": "p3",
      "text": "عند اكتشاف أي حادثة تتعلق بالوصول غير المصرح به للبيانات، تلتزم الجهة التقنية المسؤولة بإخطار إدارة الشركة خلال أربع وعشرين ساعة، لتتولى الشركة بدورها إبلاغ الجهة المختصة فوراً وتنبيه المستخدمين المتضررين إذا تطلب الأمر."
    },
    {
      "slot": "p4",
      "text": "نرسل للمستخدمين حصراً الرسائل الخدمية الضرورية المرتبطة بتأكيد الطلبات وتحديثات الحساب، وتكون هذه الرسائل خالية من أي محتوى تسويقي."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية المتممة عبر المنصة لرسوم إدارية تُحتسب بنسبة مئوية من إجمالي قيمة الخدمة وتُضاف تلقائياً عند إتمام الدفع.",
    "تتم عملية السداد حصراً عبر قنوات الدفع الإلكترونية المعتمدة والمربوطة بالبوابة المالية للشركة دون تحمل المنصة لأي مسؤولية عن تعثر العمليات الناتجة عن أعطال بنكية.",
    "يحق لأي من الطرفين إنهاء هذه الاتفاقية بموجب إشعار خطي يوجه للطرف الآخر قبل موعد الإلغاء بثلاثين يوماً تقويمياً على الأقل دون توضيح الأسباب.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التجارية الناشئة عن سوء استخدام الخدمات المقدمة.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية وتختص المحاكم المختصة بالنظر في أي نزاع ينشأ عنها."
  ]
}
